DROP TABLE IF EXISTS `movimenti`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `movimenti` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `conto_id` int(10) unsigned NOT NULL,
  `tipo` enum('ENTRATA','USCITA') NOT NULL,
  `importo` decimal(15,2) NOT NULL,
  `descrizione` varchar(255) NOT NULL,
  `categoria` varchar(100) DEFAULT NULL,
  `data_movimento` date NOT NULL,
  `note` text DEFAULT NULL,
  `annullato_il` datetime(6) DEFAULT NULL,
  `creato_il` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `aggiornato_il` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE current_timestamp(6),
  PRIMARY KEY (`id`),
  KEY `idx_movimenti_conto_data` (`conto_id`,`data_movimento`),
  KEY `idx_movimenti_annullati` (`annullato_il`),
  CONSTRAINT `fk_movimenti_conto` FOREIGN KEY (`conto_id`) REFERENCES `conti` (`id`),
  CONSTRAINT `chk_movimenti_importo` CHECK (`importo` > 0)
) ENGINE=InnoDB AUTO_INCREMENT=401 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
